selected.compute:
options = read('/input/options')
result = []
for k in range(goal['min_count'], goal['max_count'] + 1):
    for rows in combinations(options, k):
        trial = []
        for r in rows:
            trial = trial + [r['id']]
        if valid(trial):
            result = trial
            break
    if result:
        break

selected.effects:
if exists('/output/selection'):
    selection = read('/output/selection')
else:
    selection = result
    write('/output/selection', selection)
receipt_state = receipt('report')
if receipt_state == 'unattempted':
    send('report', 'team', selection)
elif receipt_state == 'unknown':
    status_state = status('report')
    if status_state == 'not_sent':
        send('report', 'team', selection)
if exists('/tmp/cache'):
    delete('/tmp/cache')
